#include <iostream>
using namespace std;

int main() {
    int a = 1000000;
    int b = 1000000;

    long long wrongAnswer = a * b; // Có thể overflow trước khi gán.
    long long correctAnswer = 1LL * a * b; // Ép phép nhân sang long long.

    cout << wrongAnswer << '\n';
    cout << correctAnswer << '\n';
    return 0;
}

#include <iostream>
#include <cctype>
using namespace std;

int main() {
    char character = 'g';
    char digit = '8';

    cout << static_cast<int>(character) << '\n'; // Mã ASCII: 103.
    cout << character - 'a' << '\n'; // Vị trí chữ cái: 6.
    cout << static_cast<char>(character - 'a' + 'A') << '\n'; // G.
    cout << digit - '0' << '\n'; // 8.
    cout << (isdigit(digit) ? "YES" : "NO") << '\n';
    cout << static_cast<char>(toupper(character)) << '\n'; // G.
    return 0;
}
